def _reference_entries(text: str) -> list[Entry]:
    seen: list[str] = []
    for name in re.findall(r"@\[([^\]]+)\]", text):
        if name not in seen:
            seen.append(name)
    return [Entry(Ref("unknown", name)) for name in seen]


@pytest.mark.parametrize("unit_id", list(UNITS))
def test_legacy_project_units_fail_closed_until_h3_native_english_rewrite(unit_id: str) -> None:
    case = UNITS[unit_id]
    text = str(case["text"])
    entries = _reference_entries(text)
    with pytest.raises(H3PromptCompileError, match="non-English execution prose"):
        compile_reference_video_provider_prompt(
            source_prompt=text,
            fallback_prompt=text,
            model_name="minimax_h3_zm_u24",
            duration_seconds=int(case["duration"]),
            request_assets=entries,
            payload={"prompt_compiler": "auto"},
            unit_id=unit_id,
        )